import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = None
        self.open_spi()

    def open_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except (OSError, IOError) as e:
            print(f"Error opening SPI device: {e}")
            sys.exit(1)

    def send_spi_command(self, spi, data):
        try:
            return spi.xfer2([0x01, 0x80, 0x00])
        except (OSError, IOError) as e:
            print(f"Error sending SPI command: {e}")
            sys.exit(1)

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        response = self.send_spi_command(self.spi, None)
        return self.extract_10bit(response)

    def convert_to_weight(self, raw_data):
        return float(raw_data) * (5.0 / 1023.0)

    def close(self):
        if self.spi:
            self.spi.close()

def main():
    reader = LoadCellReader()
    try:
        while True:
            raw_data = reader.read_raw_data()
            weight = reader.convert_to_weight(raw_data)
            print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        reader.close()

if __name__ == "__main__":
    main()

import smbus2
import signal
import sys
import logging

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.bus = smbus2.SMBus(busnum)
        self.address = address
        self.debug = debug
        if self.debug:
            logging.basicConfig(level=logging.DEBUG)
        try:
            self.bus.read_byte_data(self.address, 0x00)  # Verify the device is present
        except IOError as e:
            logging.error(f"Error verifying device: {e}")
            raise

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            config = (1 << 15) | (channel << 12) | (pga << 9) | (sps << 3)
            self.bus.write_byte_data(self.address, 0x01, config)
            return self.bus.read_word_data(self.address, 0x00)
        except IOError as e:
            logging.error(f"Error reading ADC: {e}")
            raise

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            config = (1 << 15) | (channel << 12) | (pga << 9) | (sps << 3) | (1 << 2)
            self.bus.write_byte_data(self.address, 0x01, config)
        except IOError as e:
            logging.error(f"Error starting continuous conversion: {e}")
            raise

    def get_last_conversion_results(self):
        try:
            return self.bus.read_word_data(self.address, 0x00)
        except IOError as e:
            logging.error(f"Error getting last conversion results: {e}")
            raise

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            config = (1 << 15) | (channel << 12) | (pga << 9) | (sps << 3) | (1 << 2) | (1 << 1)
            if active_low:
                config |= (1 << 0)
            if traditional_mode:
                config |= (1 << 4)
            if latching:
                config |= (1 << 5)
            self.bus.write_byte_data(self.address, 0x01, config)
            self.bus.write_word_data(self.address, 0x02, threshold_high)
            self.bus.write_word_data(self.address, 0x03, threshold_low)
        except IOError as e:
            logging.error(f"Error starting single-ended comparator: {e}")
            raise

    def close(self):
        self.bus.close()

def signal_handler(sig, frame):
    print('Closing I2C bus...')
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)

