import spidev
import RPi.GPIO as GPIO
import time
import logging

class SmartGardenController:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.gpio = GPIO
        self.gpio.setmode(GPIO.BCM)
        self.gpio.setup(18, GPIO.OUT)
        self.pump = GPIO.PWM(18, 50)
        self.pump.start(0)
        self.dry_threshold = 450
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1350000

    def read_moisture(self):
        try:
            self.spi.xfer2([1, 0b10000000, 0])
            moisture = self.spi.xfer2([0, 0, 0])[1]
            return moisture
        except Exception as e:
            logging.error(f"Error reading moisture: {e}")
            return None

    def run_pump(self, seconds):
        self.pump.ChangeDutyCycle(100)
        time.sleep(seconds)
        self.pump.ChangeDutyCycle(0)

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture is not None:
            logging.info(f"Moisture reading: {moisture}")
            if moisture > self.dry_threshold:
                self.run_pump(2)
                return True
        return False

    def close(self):
        self.pump.stop()
        self.gpio.cleanup()
        self.spi.close()

def schedule_cycles(controller, cycle_count, interval_seconds):
    try:
        for _ in range(cycle_count):
            controller.irrigation_cycle()
            time.sleep(interval_seconds)
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt received, stopping cycles.")
    finally:
        controller.close()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        logging.error(f"Error in main block: {e}")

