import spidev
import RPi.GPIO as GPIO

class SoundSensor(threading.Thread):
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue):
        threading.Thread.__init__(self)
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False

    def run(self):
        self.running = True
        if self.sensor_type == 'digital':
            self.run_digital()
        elif self.sensor_type == 'analog':
            self.run_analog()
        else:
            logging.error(f"Invalid sensor type: {self.sensor_type}")

    def run_digital(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.gpio_pins, GPIO.IN)
        while self.running:
            for pin in self.gpio_pins:
                if GPIO.input(pin) == 1:
                    self.log_queue.put(f"Sensor {self.sensor_id} detected sound")
                    time.sleep(0.1)
            time.sleep(1 / self.sample_rate)

    def run_analog(self):
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = self.spi_speed
        while self.running:
            for channel in self.channels:
                r = spi.xfer2([1, (8 + channel) << 4, 0])
                adc = ((r[1] & 3) << 8) + r[2]
                if adc >= self.threshold:
                    self.log_queue.put(f"Sensor {self.sensor_id} detected sound")
                    time.sleep(0.1)
            time.sleep(1 / self.sample_rate)
        spi.close()

    def stop(self):
        self.running = False
        if self.sensor_type == 'digital':
            GPIO.cleanup(self.gpio_pins)

def main():
    # Parse command line arguments
    # ...

    # Create log queue
    log_queue = queue.Queue()

    # Create sensors
    sensors = []
    for sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed in zip(sensor_ids, sensor_types, thresholds, sample_rates, gpio_pins_list, channels_list, spi_speeds):
        sensor = SoundSensor(sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue)
        sensors.append(sensor)

    # Start threads
    for sensor in sensors:
        sensor.start()

    # Handle KeyboardInterrupt
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        for sensor in sensors:
            sensor.join()

if __name__ == "__main__":
    main()

import spidev
import time
import signal
import sys

class MQ2Sensor:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 500000
        self.safe_limit = 150
        self.warning_limit = 400

    def read_adc(self):
        try:
            response = self.spi.xfer2([1, 0x80, 0])
            adc = ((response[1] & 3) << 8) + response[2]
            return adc
        except OSError as e:
            print(f"SPI bus error: {e}")
            sys.exit(1)

    def convert_to_ppm(self, adc):
        voltage = (adc / 1023) * 3.3
        ppm = voltage * 200
        return ppm

    def check_alert(self, ppm):
        if ppm < self.safe_limit:
            return "Safe"
        elif ppm < self.warning_limit:
            return "Warning"
        else:
            return "Danger"

    def sample_and_print(self):
        for _ in range(12):
            adc = self.read_adc()
            ppm = self.convert_to_ppm(adc)
            alert = self.check_alert(ppm)
            print(f"PPM: {ppm}, Alert: {alert}")
            time.sleep(0.5)

    def close_spi(self, signum, frame):
        self.spi.close()
        sys.exit(0)

    def run(self):
        signal.signal(signal.SIGINT, self.close_spi)
        signal.signal(signal.SIGTERM, self.close_spi)
        self.sample_and_print()

if __name__ == "__main__":
    sensor = MQ2Sensor()
    sensor.run()

