import math
from typing import Tuple, Real

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("Input must be a real number.")

    degrees = int(degrees_decimal)
    minutes = int((degrees_decimal - degrees) * 60)
    seconds = (degrees_decimal - degrees - minutes / 60) * 3600

    if degrees < 0:
        degrees = -degrees
        minutes = -minutes
        seconds = -seconds

    return degrees, minutes, seconds

def number_to_exif_rational(number: Real) -> Tuple[int, int]:
    if not isinstance(number, (int, float)):
        raise ValueError("Input must be a real number.")

    if number == 0:
        return 0, 1

    numerator = int(number * 1000)
    denominator = 1000

    if numerator % denominator != 0:
        raise ValueError("Cannot convert to a fraction.")

    return numerator, denominator

import cv2
import numpy as np
import serial
import serial.tools.list_ports
import time
import signal
import sys

# Initialize serial port
def init_serial():
    ports = serial.tools.list_ports.comports()
    for port in ports:
        if 'ACM' in port.description:
            return serial.Serial('/dev/ttyACM0', 9600)
        elif 'USB' in port.description:
            return serial.Serial(port.device, 9600)
    return None

# Initialize video capture
def init_video():
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open video device.")
        return None
    return cap

# Initialize signal handlers
def init_signal_handlers():
    def signal_handler(sig, frame):
        print('You pressed Ctrl+C!')
        cleanup()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

# Cleanup function
def cleanup():
    cap.release()
    if ser:
        ser.close()
    cv2.destroyAllWindows()

# Main function
def main():
    global ser
    ser = init_serial()
    cap = init_video()
    if not cap or not ser:
        cleanup()
        return

    init_signal_handlers()

    while True:
        ret, frame = cap.read()
        if not ret:
            print("Error: Could not read frame.")
            break

        hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
        roi = frame[50-50:50+50, 50-50:50+50]
        h, s, v = cv2.split(hsv)
        min_HSV = np.array([np.min(h), np.min(s), np.min(v)])
        max_HSV = np.array([np.max(h), np.max(s), np.max(v)])

        mask = cv2.inRange(hsv, min_HSV, max_HSV)
        contours, hierarchy = cv2.findContours(mask, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

        for cnt in contours:
            if cv2.contourArea(cnt) > 500:
                x, y, w, h = cv2.boundingRect(cnt)
                cv2.rectangle(frame, (x, y), (x+w, y+h), (255, 0, 0), 2)

                if y+h > 100:
                    if x+w > 100:
                        print('1')
                        ser.write(b'1')
                    else:
                        print('2')
                        ser.write(b'2')
                else:
                    if x+w > 100:
                        print('3')
                        ser.write(b'3')
                    else:
                        print('4')
                        ser.write(b'4')

        cv2.imshow('frame', frame)
        if cv2.waitKey(1) & 0xFF == ord('q'):
            break

    cleanup()

if __name__ == "__main__":
    main()

