import adafruit_dht
import RPi.GPIO as GPIO
import speech_recognition as sr

# Importing libraries
try:
    from gpiozero import LED
    from picamera2 import Picamera2
    from adafruit_dht import DHT11
except ImportError:
    print("Some libraries are missing. Please install them.")
    sys.exit(1)

# GPIO setup
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)
try:
    led = LED(17)
except RuntimeError:
    print("GPIO initialization failed. Falling back to simulation mode.")
    led = None

# DHT11 setup
try:
    dht_sensor = DHT11(4)
except RuntimeError:
    print("DHT11 sensor initialization failed. Falling back to simulation mode.")
    dht_sensor = None

# Camera setup
try:
    camera = Picamera2()
    camera.configure("640x480")
except RuntimeError:
    print("Camera initialization failed. Falling back to simulation mode.")
    camera = None

# Function to turn lights on
def turn_lights_on():
    if led:
        led.on()
    else:
        print("Lights turned on (simulated).")

# Function to turn lights off
def turn_lights_off():
    if led:
        led.off()
    else:
        print("Lights turned off (simulated).")

# Function to read temperature
def read_temperature():
    if dht_sensor:
        try:
            temperature = dht_sensor.temperature
        except RuntimeError:
            print("Failed to read temperature. Falling back to simulation mode.")
            temperature = random.uniform(15, 35)
    else:
        temperature = random.uniform(15, 35)
        print("Temperature read (simulated): {:.2f}°C".format(temperature))
    return temperature

# Function to take a picture
def take_picture():
    if camera:
        timestamp = time.strftime("%Y%m%d%H%M%S")
        filename = "greenhouse_{}.jpg".format(timestamp)
        camera.capture_file(filename)
        print("Picture taken and saved as {}".format(filename))
    else:
        print("Camera unavailable. Picture not taken (simulated).")

# Function to handle voice commands
def handle_voice_command(command):
    if "turn on the lights" in command:
        turn_lights_on()
    elif "turn off the lights" in command:
        turn_lights_off()
    elif "what is the temperature" in command:
        read_temperature()
    elif "take a picture" in command:
        take_picture()
    else:
        print("Unknown command.")

# Main function
def main():
