import serial
import sys

class SerialPort:
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.ser = None

    def __enter__(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate)
        except serial.SerialException as e:
            print(f"Failed to open serial port {self.port}: {e}", file=sys.stderr)
            sys.exit(1)
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self.ser:
            self.ser.close()

    def write(self, data):
        try:
            self.ser.write(data.encode('utf-8'))
            print(f"Sent {len(data)} bytes: {data}", file=sys.stderr)
        except serial.SerialException as e:
            print(f"Failed to write to serial port {self.port}: {e}", file=sys.stderr)

def main():
    port = '/dev/rfcomm4'
    baudrate = 38400

    with SerialPort(port, baudrate) as ser:
        while True:
            try:
                user_input = input("Enter data to send (or 'q' to quit): ")
                if user_input.lower() == 'q':
                    break
                ser.write(f"X{user_input}")
            except KeyboardInterrupt:
                print("\nExiting...", file=sys.stderr)
                break

