import picamera2
import cv2
import numpy as np
import io
import logging

class CameraStreamBuffer:
    def __init__(self, c):
        self.c = c
        self.b = io.BytesIO()
        self.frame_type = None

    def write(self, d):
        self.b.write(d)
        frame_type = self.c.current_configuration()['encode']['frame_type']
        if frame_type != 1:
            if self.frame_type == 1:
                try:
                    self.b.seek(0)
                    output = io.BytesIO()
                    self.b.seek(4)  # Skip the initial 00 00 00 01 start code.
                    while True:
                        chunk = self.b.read(188)  # Read one TS packet.
                        if not chunk:
                            break
                        output.write(chunk)
                    output.seek(0)
                    # Here you can process the output bytes as needed.
                    output.close()
                except IOError as e:
                    logging.error(f"Error writing frame: {e}")
                finally:
                    self.b = io.BytesIO()
            self.frame_type = frame_type
        else:
            self.frame_type = frame_type

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.previous_frame = None
        self.current_frame = None
        self.current_frame_buffer = b""

    def write(self, d):
        while b"\xff\xd8" in d:
            if self.current_frame is not None:
                self.f(self.previous_frame, self.current_frame)
            self.previous_frame = self.current_frame
            self.current_frame = None
            self.current_frame_buffer = b""
            d = d[d.index(b"\xff\xd8") + 2:]
        self.current_frame_buffer += d
        try:
            self.current_frame = cv2.imdecode(np.frombuffer(self.current_frame_buffer, np.uint8), cv2.IMREAD_COLOR)
        except cv2.error as e:
            logging.error(f"Error decoding frame: {e}")
            self.current_frame_buffer = b""

