import smbus2
import time
import logging
from gpiozero import CPUTemperature

class DHT20Sensor:
    def __init__(self):
        self.bus = None
        self.logger = logging.getLogger(__name__)
        try:
            self.bus = smbus2.SMBus(1)
            time.sleep(0.5)
            status = self.bus.read_byte_data(0x38, 0x71)
            if (status & 0x18) != 0x18:
                self.logger.error("DHT20 not ready")
                return False
        except Exception as e:
            self.logger.error("Failed to open I2C bus: %s", e)
            return False

    def __del__(self):
        if self.bus:
            self.bus.close()

    def get_temperature_and_humidity(self):
        for _ in range(5):
            try:
                self.bus.write_i2c_block_data(0x38, 0xAC, [0x33, 0x00])
                status = 0x80
                while status & 0x80:
                    time.sleep(0.1)
                    status = self.bus.read_byte_data(0x38, 0x71)
                    if status & 0x80:
                        self.logger.warning("DHT20 measurement timeout")
                data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
                raw_H = (data[1] << 16) | (data[2] << 8) | data[3]
                raw_T = (data[4] << 16) | (data[5] << 8) | (data[6] & 0xF0)
                temperature = raw_T / 5242.88 - 50
                humidity = raw_H / 1048576 * 100
                crc = data[6] & 0x0F
                crc_calculated = self.calculate_crc8(data[:6], 0xFF)
                if crc_calculated != crc:
                    self.logger.warning("DHT20 CRC mismatch")
                    continue
                return (temperature, humidity, False)
            except Exception as e:
                self.logger.error("Failed to read DHT20 data: %s", e)
        return (None, None, True)

    def calculate_crc8(self, data, initial_value):
        crc = initial_value
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
        return crc & 0xFF

import time
import csv
import RPi.GPIO as GPIO

DHT_PIN = 4

def read_dht22():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(DHT_PIN, GPIO.OUT)
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(0.018)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        pass
    while GPIO.input(DHT_PIN) == GPIO.LOW:
        pass
    bits = []
    for _ in range(40):
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            pass
        high = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            pass
        low = time.time()
        bits.append((low - high) > 0.00026)
    GPIO.cleanup()
    if sum(bits[:8]) != 0 or sum(bits[8:16]) != 1 or sum(bits[16:24]) != 0 or sum(bits[24:32]) != 1 or sum(bits[32:40]) != 1:
        return (None, None)
    humidity = sum(bits[16:24]) * 256 + sum(bits[24:32]) * 128 + sum(bits[32:40]) * 64
    temperature = sum(bits[8:16]) * 256 + sum(bits[16:24]) * 128 + sum(bits[24:32]) * 64
    if bits[32]:
        temperature = -temperature
    return (temperature / 1024.0, humidity / 1024.0)

