import sys
import time
import logging

class DHT20:
    def __init__(self):
        self.bus = None
        self.crc_error = False
        try:
            self.bus = smbus2.SMBus(1)
            self.bus.write_byte_data(0x38, 0x71)
            if self.bus.read_byte_data(0x38, 0x71) != 0x71:
                logging.error("DHT20 not found")
                self.bus = None
        except Exception as e:
            logging.error(f"Failed to initialize DHT20: {e}")
            self.bus = None

    def measure(self):
        if self.bus is None:
            return (None, None, True)

        try:
            self.bus.write_byte_data(0x38, 0xAC, bytearray([0x33, 0x00]))
            start_time = time.time()
            while True:
                status = self.bus.read_byte_data(0x38, 0x71)
                if (status & 0x80) == 0:
                    break
                if time.time() - start_time > 0.1:
                    logging.error("DHT20 measurement timeout")
                    return (None, None, True)
                time.sleep(0.01)

            data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
            crc = 0xFF
            for byte in data[:6]:
                crc = crc ^ byte
                for _ in range(8):
                    crc = (crc << 1) & 0xFF if (crc & 0x80) != 0 else crc << 1
            self.crc_error = crc != data[6]

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]
            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return (temperature, humidity, self.crc_error)
        except Exception as e:
            logging.error(f"Failed to measure from DHT20: {e}")
            return (None, None, True)

    def __del__(self):
        if self.bus is not None:
            self.bus.close()

def signal_handler(sig, frame):
    print("Exiting...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    dht20 = DHT20()
    if dht20.bus is not None:
        temperature, humidity, crc_error = dht20.measure()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%, CRC Error: {crc_error}")
        else:
            print("Failed to measure from DHT20")
    else:
        print("DHT20 not found")

