import smbus2
import time
import logging
import contextlib
import picamera2
import adafruit_dht
import gpiozero
import paho.mqtt.client as mqtt

class DHT20Sensor:
    def __init__(self, bus=1, address=0x38):
        self.bus = smbus2.SMBus(bus)
        self.address = address
        self.last_read_time = 0
        self.temperature = None
        self.humidity = None
        self.busy = False
        self.attempts = 0

    def begin(self):
        try:
            self.bus.open(1)
            time.sleep(0.5)
            status = self.bus.read_byte_data(self.address, 0x71)
            if (status & 0x18) != 0x18:
                logging.error("Sensor status check failed.")
                return False
            self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
            for _ in range(10):
                time.sleep(0.08)
                status = self.bus.read_byte_data(self.address, 0x71)
                if not (status & 0x80):
                    break
            else:
                logging.error("Measurement timeout.")
                return False
            data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            crc = 0xFF
            for byte in data[:-1]:
                crc ^= byte
            if crc != data[-1]:
                logging.warning("CRC mismatch.")
                return self.begin()
            humidity_raw = (data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4)
            self.humidity = humidity_raw / 2**20 * 100
            temperature_raw = (data[3] & 0x0F) << 16 | (data[4] << 8) | data[5]
            self.temperature = temperature_raw / 2**19 * 200 - 50
            self.attempts = 0
            return True
        except OSError as e:
            logging.error(f"Bus error: {e}")
            return False

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_read_time < 2:
            return self.temperature, self.humidity, False
        if not self.begin():
            self.attempts += 1
            if self.attempts >= 5:
                return None, None, True
            time.sleep(0.01)
            return self.get_temperature_and_humidity()
        self.last_read_time = current_time
        return self.temperature, self.humidity, False

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

