    elif temperature > 50:
        fan.duty_cycle = 0.70
    elif temperature > 40:
        fan.duty_cycle = 0.50
    elif temperature > 32:
        fan.duty_cycle = 0.25
    elif temperature > 25:
        fan.duty_cycle = 0.15
    else:
        fan.duty_cycle = 0.0

