from datetime import datetime

class CleanEnergyMonitor:
    def __init__(self, motion_sensor_pin=17, debounce_interval=2.0, sample_count=10, sample_interval=0.5):
        self.motion_sensor = None
        self.debounce_interval = debounce_interval
        self.sample_count = sample_count
        self.sample_interval = sample_interval
        self.motion_events = []
        self.initialize_sensor(motion_sensor_pin)

    def initialize_sensor(self, motion_sensor_pin):
        try:
            self.motion_sensor = MotionSensor(motion_sensor_pin)
        except Exception as e:
            print(f"Failed to initialize motion sensor: {e}")
            sys.exit(1)

    def log_motion_event(self):
        self.motion_events.append(datetime.now().isoformat())

    def get_occupancy_statistics(self):
        return len(self.motion_events)

    def sample_sensor(self):
        for _ in range(self.sample_count):
            self.motion_sensor.wait_for_motion()
            self.log_motion_event()
            time.sleep(self.sample_interval)

    def print_summary_report(self):
        print(f"Total motion events: {self.get_occupancy_statistics()}")

    def run(self):
        try:
            self.sample_sensor()
            self.print_summary_report()
        except Exception as e:
            print(f"Runtime error: {e}")
            sys.exit(1)
        finally:
            if self.motion_sensor:
                self.motion_sensor.close()

