        elif self.dig_out:
            self.dig_out.value = gpiozero.HIGH if self.global_err_state else gpiozero.LOW

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def cleanup(self):
        if self.pwm_out:
            self.pwm_out.close()
        elif self.dig_out:
            self.dig_out.close()

    def handle_message(self):
        while True:
            try:
                message = self.sub_socket.recv(zmq.NOBLOCK)
                self.last_msg = time.time()
                # process message and update PID parameters
            except zmq.error.EAGAIN:
                if time.time() - self.last_msg > 20:
                    self.set_error_output(True)
            except Exception as e:
                logging.error(f"Message handling failed: {e}")
                break

    def run(self):
        context = zmq.Context()
        self.sub_socket = context.socket(zmq.SUB)
        self.sub_socket.connect("tcp://localhost:5555")
        self.sub_socket.setsockopt_string(zmq.SUBSCRIBE, "")

        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        try:
            while True:
                self.handle_message()
        except KeyboardInterrupt:
            pass
        finally:
            self.cleanup()

    def signal_handler(self, signal, frame):
        self.cleanup()
        sys.exit(0)

if __name__ == "__main__":
    logging.basicConfig(level=logging.ERROR)
    pid_handler = PIDHandler(pwm=True)
    pid_handler.run()

