import pigpio
import time

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not 0 <= pin_number <= 31:
            raise ValueError("Invalid pin number. Must be in range 0-31.")
        if not isinstance(initial_value, int) or initial_value not in [0, 1]:
            raise ValueError("Invalid initial value. Must be 0 or 1.")

        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pi = None

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise ConnectionError("Failed to connect to pigpio daemon.")
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
            self.pi.write(self.pin_number, self.initial_value)
        except Exception as e:
            self.shutdown()
            raise e

    def set_value(self, value: int):
        if not isinstance(value, int) or value not in [0, 1]:
            raise ValueError("Invalid value. Must be 0 or 1.")
        self.pi.write(self.pin_number, value)

    def shutdown(self):
        if self.pi:
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
            self.pi.stop()

