import sys
import logging
import signal
import gpiozero
from gpiozero.pins.pigpio import PiGPIOFactory

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.state_table = {0: {0: 0, 1: 1}, 1: {0: 3, 1: 2}, 2: {0: 2, 1: 3}, 3: {0: 1, 1: 0}}
        self._setup_signals()
        self._setup_pins()
        self._setup_event_handlers()

    def _setup_signals(self):
        for sig in [signal.SIGINT, signal.SIGTERM]:
            signal.signal(sig, self._cleanup)

    def _setup_pins(self):
        try:
            self.clk = gpiozero.InputDevice(self.clk_pin, pull_up=True, bounce_time=0.02)
            self.dt = gpiozero.InputDevice(self.dt_pin, pull_up=True, bounce_time=0.02)
        except Exception as e:
            logging.error(f"Failed to setup pins: {e}")
            self._cleanup()

    def _setup_event_handlers(self):
        self.clk.when_activated = self._on_clk_rising
        self.clk.when_deactivated = self._on_clk_falling
        self.dt.when_activated = self._on_dt_rising
        self.dt.when_deactivated = self._on_dt_falling

    def _on_clk_rising(self):
        self._update_counter(self.clk.value)

    def _on_clk_falling(self):
        self._update_counter(self.clk.value)

    def _on_dt_rising(self):
        self._update_counter(self.dt.value)

    def _on_dt_falling(self):
        self._update_counter(self.dt.value)

    def _update_counter(self, clk_value):
        new_state = self.state_table[self.state][clk_value]
        if new_state != self.state:
            self.state = new_state
            if self.state == 1:
                self.counter += 1
            elif self.state == 3:
                self.counter -= 1
            if self.callback:
                try:
                    self.callback(self.counter)
                except Exception as e:
                    logging.error(f"Callback failed: {e}")

    def _cleanup(self, *args):
        logging.info("Cleaning up...")
        self.clk.close()
        self.dt.close()
        sys.exit(0)

    def cleanup(self):
        self._cleanup()

if __name__ == "__main__":
    try:
        encoder = RotaryEncoder(17, 18, lambda x: print(f"Counter: {x}"))
        while True:
            pass
    except Exception as e:
        logging.error(f"Main failed: {e}")
        encoder.cleanup()

