import paho.mqtt.client as mqtt
import time
import sys

class RotaryEncoder:
    def __init__(self, callback=None):
        if callback and not callable(callback):
            raise TypeError("callback must be callable")
        self._callback = callback
        self._clk = gpiozero.InputDevice(17, pull_up=True, bounce_time=0.005)
        self._dt = gpiozero.InputDevice(18, pull_up=True, bounce_time=0.005)
        self._clk.when_activated = self._on_clk_activate
        self._clk.when_deactivated = self._on_clk_deactivate
        self._counter = 0
        self._last_clk_state = self._clk.value

    def _on_clk_activate(self):
        if self._clk.value == self._last_clk_state:
            return
        if self._dt.value == self._clk.value:
            self._counter += 1
        else:
            self._counter -= 1
        self._last_clk_state = self._clk.value
        if self._callback:
            try:
                self._callback(self._counter)
            except Exception as e:
                print(f"Exception in callback: {e}", file=sys.stderr)

    def _on_clk_deactivate(self):
        if self._clk.value == self._last_clk_state:
            return
        if self._dt.value == self._clk.value:
            self._counter -= 1
        else:
            self._counter += 1
        self._last_clk_state = self._clk.value
        if self._callback:
            try:
                self._callback(self._counter)
            except Exception as e:
                print(f"Exception in callback: {e}", file=sys.stderr)

    def cleanup(self):
        self._clk.close()
        self._dt.close()

def main():
    def on_counter(counter):
        print(f"Counter: {counter}")

    encoder = RotaryEncoder(on_counter)
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        encoder.cleanup()

