import pigpio
import time

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pi, pin):
        if not isinstance(pi, pigpio.pi):
            raise MotorError("Invalid or disconnected pigpio.pi instance.")
        self.pi = pi
        self.pin = pin
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.set_PWM_frequency(self.pin, 1000)
        self.pi.set_PWM_dutycycle(self.pin, 0)
        self.duty = 0

    def set_frequency(self, freq):
        if not isinstance(freq, int) or freq < 1:
            raise MotorError("Invalid frequency.")
        self.pi.set_PWM_frequency(self.pin, freq)

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError("Invalid duty cycle.")
        self.duty = duty
        self.pi.set_PWM_dutycycle(self.pin, duty)

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.stop()
        self.pi.stop()

    def __del__(self):
        self.close()

import RPi.GPIO as GPIO
import time
import logging
from picamera2 import Picamera2

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

class ServoController:
    def __init__(self, pin=18):
        self.pin = pin
        self.duty_cycle_min = 2.5 / 100
        self.duty_cycle_max = 12.5 / 100
        self.duty_cycle_range = self.duty_cycle_max - self.duty_cycle_min
        self.pwm_frequency = 50
        self.setup_gpio()

    def setup_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.pin, GPIO.OUT)
        self.pwm = GPIO.PWM(self.pin, self.pwm_frequency)
        self.pwm.start(0)

    def move_to(self, angle):
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.pwm.ChangeDutyCycle(duty_cycle)
        logging.info(f"Moved to angle {angle} with duty cycle {duty_cycle}")

    def stop(self):
        self.pwm.stop()
        GPIO.cleanup()

    def _angle_to_duty_cycle(self, angle):
        return self.duty_cycle_min + (self.duty_cycle_range * angle / 180)

def main(angles):
    try:
        servo = ServoController()
        for angle in angles:
            servo.move_to(angle)
            time.sleep(0.5)
        servo.stop()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
        servo.stop()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        servo.stop()

