        'OPMODE': {'R/W': 'W', 'Register': 0x3500, 'functioncode': 6, 'Value': {'Position': 1}},
        'VelocityFeedback': {'R/W': 'R', 'Register': 0x3B00, 'functioncode': 3, 'read_length': 2},
        'PositionFeedback': {'R/W': 'R', 'Register': 0x3700, 'functioncode': 3, 'read_length': 2},
        'PositionCommand': {'R/W': 'W', 'Register': 0x4000, 'functioncode': 16},
        'VelocityCommand': {'R/W': 'W', 'Register': 0x6F00, 'functioncode': 16}
    }

    def __init__(self, port='/dev/serial0', baudrate=115200):
        self.port = port
        self.baudrate = baudrate
        self.client = None
        self.logger = logging.getLogger(__name__)

    def connect(self):
        try:
            self.client = ModbusClient(method='rtu', port=self.port, baudrate=self.baudrate, timeout=1)
            self.client.connect()
        except Exception as e:
            self.logger.error(f"Failed to connect to Modbus RTU servo motor controller: {e}")
            sys.exit(1)

    def read_register(self, register):
        try:
            response = self.client.read_holding_registers(address=register['Register'], count=register['read_length'], unit=1)
            return response.registers
        except Exception as e:
            self.logger.error(f"Failed to read register {register['Register']:04X}: {e}")
            return None

    def write_register(self, register, value):
        try:
            if register['R/W'] == 'W':
                self.client.write_register(address=register['Register'], value=value, unit=1)
            elif register['R/W'] == 'R':
                self.logger.error(f"Attempted to write to read-only register {register['Register']:04X}")
                return False
        except Exception as e:
            self.logger.error(f"Failed to write to register {register['Register']:04X}: {e}")
            return False
        return True

    def close(self):
        if self.client:
            self.client.close()

# Handle graceful shutdown
def signal_handler(sig, frame):
    print('Shutting down...')
    servo.close()
    sys.exit(0)

if __name__ == "__main__":
    logging.basicConfig(level=logging.ERROR)
    signal.signal(signal.SIGINT, signal_handler)
    servo = ModbusServo()
    servo.connect()
    try:
        # Example usage: read and write registers
        status = servo.read_register(ModbusServo.register_map['STATUS'])
        print(f"Status: {status}")
        servo.write_register(ModbusServo.register_map['PositionCommand'], 100)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        servo.close()

