import serial
import minimalmodbus
import signal
import sys
import time
import logging

class ModbusServo:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.bus = None
        self.logger = logging.getLogger(__name__)

    def open_bus(self):
        try:
            self.bus = minimalmodbus.Instrument(self.port, self.slave_address)
            self.bus.serial.baudrate = self.baudrate
            self.bus.serial.bytesize = 8
            self.bus.serial.parity = 'N'
            self.bus.serial.stopbits = 1
            self.bus.serial.timeout = 0.5
        except serial.SerialException as e:
            self.logger.error(f"Failed to open serial port: {e}")
            sys.exit(1)

    def close_bus(self):
        if self.bus:
            self.bus.close()

    def set_operation_mode(self, mode):
        try:
            self.bus.write_register(0x3500, mode)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to set operation mode: {e}")
            raise

    def write_position_command(self, value):
        try:
            self.bus.write_register(0x4000, value)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to write position command: {e}")
            raise

    def write_velocity_command(self, value):
        try:
            self.bus.write_register(0x6F00, value)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to write velocity command: {e}")
            raise

    def read_position_feedback(self):
        try:
            return self.bus.read_registers(0x3700, 2)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to read position feedback: {e}")
            raise

    def read_velocity_feedback(self):
        try:
            return self.bus.read_registers(0x3B00, 2)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to read velocity feedback: {e}")
            raise

    def start(self):
        try:
            self.bus.write_register(0x3100, 0x000F)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to start servo: {e}")
            raise

    def stop(self):
        try:
            self.bus.write_register(0x3100, 0x0006)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to stop servo: {e}")
            raise

    def read_status(self):
        try:
            return self.bus.read_register(0x3000)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Failed to read status: {e}")
            raise

    def run_demo(self):
        signal.signal(signal.SIGINT, signal.SIG_DFL)
        signal.signal(signal.SIGTERM, signal.SIG_DFL)

        self.open_bus()

        try:
            self.set_operation_mode(1)
            self.write_position_command(1000)
            self.write_velocity_command(500)
            self.start()

            time.sleep(2)

            position = self.read_position_feedback()
            velocity = self.read_velocity_feedback()
            status = self.read_status()

            print(f"Position: {position}, Velocity: {velocity}, Status: {status}")

        except Exception as e:
            self.logger.error(f"Demo failed: {e}")

        finally:
            self.stop()
            self.close_bus()

if __name__ == '__main__':
    logging.basicConfig(level=logging.ERROR)
    servo = ModbusServo()
    servo.run_demo()

