import adafruit_servokit
import time
import sys

class ServoController:
    def __init__(self):
        try:
            self.kit = adafruit_servokit.ServoKit(channels=16, address=0x40, i2c_bus=1)
        except OSError as e:
            print(f"Failed to initialize ServoKit: {e}")
            sys.exit(1)

    def grab_object(self, servo_num=0):
        try:
            self.validate_servo_num(servo_num)
            self.move_servo(servo_num, 90)
        except ValueError as e:
            print(f"Failed to grab object: {e}")

    def release_object(self, servo_num=0):
        try:
            self.validate_servo_num(servo_num)
            self.move_servo(servo_num, 150)
        except ValueError as e:
            print(f"Failed to release object: {e}")

    def move_servo(self, servo_num, target_angle):
        try:
            self.validate_servo_num(servo_num)
            self.validate_angle(target_angle)
            current_angle = self.kit.servo[servo_num].angle
            step = 5 if current_angle < target_angle else -5
            while current_angle != target_angle:
                current_angle += step
                self.kit.servo[servo_num].angle = current_angle
                time.sleep(0.04)
        except ValueError as e:
            print(f"Failed to move servo: {e}")

    def validate_servo_num(self, servo_num):
        if not 0 <= servo_num <= 15:
            raise ValueError(f"Invalid servo number: {servo_num}")

    def validate_angle(self, angle):
        if not 0 <= angle <= 180:
            raise ValueError(f"Invalid angle: {angle}")

    def cleanup(self):
        try:
            self.kit.exit()
        except OSError as e:
            print(f"Failed to clean up ServoKit: {e}")

if __name__ == "__main__":
    try:
        controller = ServoController()
        controller.grab_object()
        time.sleep(2)
        controller.release_object()
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        controller.cleanup()

