    if intent == 'pump_on':
        logging.info("Turning pump on")
        pump.on()
    elif intent == 'pump_off':
        logging.info("Turning pump off")
        pump.off()
    elif intent == 'light_toggle':
        logging.info("Toggling light")
        light.toggle()
    else:
        logging.warning(f"Unknown intent: {intent}")

def main():
    test_phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    for phrase in test_phrases:
        intent = parse_intent(phrase)
        execute_intent(intent)
        time.sleep(1)  # Give some time to observe the changes

    logging.info("Exiting program")
    pump.close()
    light.close()

