        try:
            return self.bus.read_byte_data(self.address, register)
        except (OSError, IOError):
            raise RuntimeError(f"Failed to read from register {register} on device at address {self.address}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

