import smbus2
import time
import datetime
import signal
import sys

class DS1338:
    def __init__(self):
        self.bus = smbus2.SMBus(1)
        try:
            self.bus.write_byte(0x68, 0x00)
        except OSError:
            print("DS1338 not found on I2C bus 1 at address 0x68")
            sys.exit(1)
        self.registers = {
            0x00: 'seconds',
            0x01: 'minutes',
            0x02: 'hours',
            0x04: 'date',
            0x05: 'month',
            0x06: 'year'
        }

    def _bcd_to_int(self, bcd):
        return int(bin(bcd), 2)

    def _int_to_bcd(self, integer):
        return int(bin(integer), 2)

    def read_register(self, register):
        try:
            value = self.bus.read_byte_data(0x68, register)
            if register == 0x02:
                value = (value & 0x3F) | 0x40
            return self._bcd_to_int(value)
        except OSError:
            print(f"Error reading {self.registers[register]} register")
            sys.exit(1)

    def write_register(self, register, value):
        try:
            if register == 0x02:
                value = (value & 0x3F) | 0x40
            self.bus.write_byte_data(0x68, register, self._int_to_bcd(value))
        except OSError:
            print(f"Error writing {self.registers[register]} register")
            sys.exit(1)

    def read_datetime(self, century=21):
        year = self.read_register(0x06) + century * 100
        month = self.read_register(0x05)
        date = self.read_register(0x04)
        hours = self.read_register(0x02)
        minutes = self.read_register(0x01)
        seconds = self.read_register(0x00)
        return datetime.datetime(year, month, date, hours, minutes, seconds)

    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
        if seconds is not None:
            self.write_register(0x00, seconds)
        if minutes is not None:
            self.write_register(0x01, minutes)
        if hours is not None:
            self.write_register(0x02, hours)
        if date is not None:
            self.write_register(0x04, date)
        if month is not None:
            self.write_register(0x05, month)
        if year is not None:
            self.write_register(0x06, year)

    def close(self):
        self.bus.close()

def signal_handler(sig, frame):
    print('Closing DS1338...')
    ds1338.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

ds1338 = DS1338()

# Test reading and writing datetime
print(ds1338.read_datetime())
ds1338.write_all(seconds=30, minutes=15, hours=12, date=25, month=12, year=23)
print(ds1338.read_datetime())

ds1338.close()

import smbus2
import datetime
import sys

class DS1338:
    def __init__(self):
        try:
            self.bus = smbus2.SMBus(1)
        except IOError as e:
            raise IOError("Failed to open SMBus: " + str(e))
        self.address = 0x68

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def read_all(self):
        registers = [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06]
        data = []
        for register in registers:
            try:
                data.append(self.bus.read_byte_data(self.address, register))
            except IOError as e:
                raise IOError("Failed to read register 0x{:02x}: {}".format(register, str(e)))
        return tuple([data[i] & 0x7f if i == 0 else data[i] for i in range(7)])

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime.datetime(2000 + (year >> 4) * 10 + (year & 0x0f),
                                    (month >> 4) * 10 + (month & 0x0f),
                                    (date >> 4) * 10 + (date & 0x0f),
                                    (hours >> 4) * 10 + (hours & 0x0f),
                                    (minutes >> 4) * 10 + (minutes & 0x0f),
                                    (seconds >> 4) * 10 + (seconds & 0x0f),
                                    tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (0 <= year <= 99 and 1 <= month <= 12 and 1 <= date <= 31 and
                 1 <= day <= 7 and 0 <= hours <= 23 and 0 <= minutes <= 59 and 0 <= seconds <= 59):
            raise ValueError("Invalid date/time value")
        registers = [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06]
        data = [seconds, minutes, hours, day, date, month, year << 4]
        for register, value in zip(registers, data):
            try:
                self.bus.write_byte_data(self.address, register, value)
            except IOError as e:
                raise IOError("Failed to write register 0x{:02x}: {}".format(register, str(e)))

    def write_datetime(self, dt):
        self.write_all(dt.year % 100, dt.month, dt.day, dt.weekday() + 1, dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_all(*self.read_all())

if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            print(rtc.read_datetime())
    except IOError as e:
        sys.stderr.write("DS1338 not found: " + str(e) + "\n")
        sys.exit(1)

import serial
import time
import signal
import sys

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Failed to open serial port {self.port}: {e}")
            sys.exit(1)

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        self.ser.write(command + b'\r\n')
        start_time = time.time()
        while True:
            if self.ser.in_waiting > 0:
                response = self.ser.read_until(wait_for)
                if wait_for in response:
                    return response
            if time.time() - start_time > timeout:
                return None

    def test_connection(self):
        response = self._send_command(b'AT')
        return response and b'OK' in response

    def restart(self):
        self._send_command(b'AT+RST')
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        self._send_command(b'AT+CWJAP="' + ssid.encode() + b'","' + password.encode() + b'"', timeout=10)
        return self.test_connection()

    def disconnect_wifi(self):
        self._send_command(b'AT+CWQAP')
        return self.test_connection()

    def get_ip(self):
        response = self._send_command(b'AT+CIFSR')
        if response and b'OK' in response:
            ip = response.split(b'+CIFSR:STAIP,')[1].split(b'\r\n')[0]
            return ip.decode()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        request = f"{method} {url} HTTP/1.1\r\nHost: {host}\r\n"
        if headers:
            for key, value in headers.items():
                request += f"{key}: {value}\r\n"
        if data:
            request += f"Content-Length: {len(data)}\r\n\r\n{data}"
        self._send_command(b'AT+CIPSTART="TCP","' + host.encode() + b'",' + str(port).encode())
        self._send_command(b'AT+CIPSEND=' + str(len(request)).encode())
        self.ser.write(request.encode())
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        response = b""
        while True:
            if self.ser.in_waiting > 0:
                data = self.ser.read(self.ser.in_waiting)
                response += data
                if b'\r\n\r\n' in response:
                    return response
            if time.time() - start_time > timeout:
                return None

    def close(self):
        if self.ser:
            self.ser.close()

def signal_handler(sig, frame):
    print('Closing serial port...')
    esp8266.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    esp8266 = ESP8266()
    print(esp8266.test_connection())
    print(esp8266.restart())
    print(esp8266.connect_wifi("your_ssid", "your_password"))
    print(esp8266.get_ip())
    print(esp8266.send_http_request("GET", "/", "example.com"))
    esp8266.close()

