def parse_nmea_sentence(sentence):
    fields = sentence.split(',')
    if fields[0] == '$GPRMC' and fields[2] == 'A':
        lat_degrees = int(fields[3][:2])
        lat_minutes = float(fields[3][2:])
        lat_direction = fields[4]
        lon_degrees = int(fields[5][:3])
        lon_minutes = float(fields[5][3:])
        lon_direction = fields[6]
        lat = lat_degrees + lat_minutes / 60
        lon = lon_degrees + lon_minutes / 60
        if lat_direction == 'S':
            lat = -lat
        if lon_direction == 'W':
            lon = -lon
        return lat, lon
    return None, None

