from flask import Flask, jsonify, request, abort
import serial
import json
import threading

app = Flask(__name__)

# In-memory data store
store = [{'id': 1, 'name': 'Item 1'}, {'id': 2, 'name': 'Item 2'}]
next_id = 3

@app.route('/version', methods=['GET'])
def version():
    try:
        with serial.Serial('/dev/ttyUSB0', 9600) as ser:
            ser.write(b'*IDN?\n')
            ser.flush()
            time.sleep(0.1)
            response = ser.read(ser.in_waiting or 1)
            return response.decode('utf-8').replace('\n', '<br>')
    except Exception as e:
        return 'Error: {}'.format(e), 503

@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(store)

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    item = next((x for x in store if x['id'] == item_id), None)
    if item is None:
        abort(404)
    return jsonify(item)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET', 'POST'])
def get_post(item_id, name):
    item = next((x for x in store if x['id'] == item_id), None)
    if item is None:
        abort(404)
    if request.method == 'POST':
        item['name'] = name
        item['done'] = request.form.get('done', 'false').lower() in ['true', '1', 't']
    return jsonify(store)

@app.route('/postjson', methods=['GET', 'POST'])
def post_json():
    if request.is_json:
        data = request.get_json()
    else:
        data = request.form.to_dict()
    new_item = {'id': next_id, 'name': data.get('name', ''), 'done': data.get('done', False)}
    store.append(new_item)
    next_id += 1
    return jsonify(store)

if __name__ == '__main__':
    app.run(host='0.0.0.0')

